const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  arrow:'M5 12h14m-6-6 6 6-6 6', arrowUp:'M7 17 17 7M7 7h10v10', chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6',
  grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z', chart:'M4 19V9m8 10V4m8 15v-7',
  layers:'m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5', file:'M14 2H5v20h14V7zm0 0v6h5M8 13h8m-8 4h5',
  shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5zm-4 9 3 3 5-5', agent:'M8 5h8v5H8zM3 16h6v5H3zm12 0h6v5h-6zM12 10v3H6v3m6-3h6v3',
  clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', lock:'M5 10h14v11H5zm3 0V6a4 4 0 0 1 8 0v4m-4 5v2',
  check:'m5 12 4 4L19 6', close:'m6 6 12 12M18 6 6 18', plus:'M12 5v14M5 12h14', menu:'M4 6h16M4 12h16M4 18h16',
  book:'M12 5C9 3 5 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-7-1-10 1v16',
  search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0', info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  logout:'M9 3H4v18h5m5-14 5 5-5 5m-7-5h12', download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',
  users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m20 0v-3a4 4 0 0 0-3-3.9M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4-3.9a4 4 0 0 1 0 7.8',
  compare:'M5 4v16m14-16v16M2 8h11l-3-3m12 11H11l3 3', eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-5 5-5 15 0 20 5-5 5-15 0-20'
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const logo = () => `<span class="logo-mark" aria-hidden="true"><i></i><b></b><em></em><small></small></span><span class="wordmark">ltef</span>`;
const sectors = {finance:'Finance',healthcare:'Healthcare',public_sector:'Public sector'};
const groups = [
  {id:'quality',name:'Performance',icon:'chart',role:'viewer',description:'Understand answer quality and how well confidence reflects correctness.',ids:['reference_accuracy','supported_claim_fraction','brier_score']},
  {id:'safety',name:'Safety & trust',icon:'shield',role:'researcher',description:'Examine harmful outcomes, privacy exposure, and appropriate human escalation.',ids:['major_clinical_error_rate','canary_disclosure_rate','attack_success_rate','benign_refusal_rate','escalation_rate']},
  {id:'agents',name:'Multi-agent',icon:'agent',role:'researcher',description:'Evaluate how agents complete tasks, coordinate, and operate within their permissions.',ids:['task_success_rate','unauthorized_tool_attempt_rate','unauthorized_tool_execution_rate','handoff_completion_rate','step_budget_exceedance_rate','trace_canary_disclosure_rate','propagated_error_rate']},
  {id:'efficiency',name:'Efficiency',icon:'clock',role:'viewer',description:'Make resource use visible alongside system quality.',ids:['latency_ms','total_tokens','cost_usd']}
];
const copy = {
  reference_accuracy:['Answer accuracy','Does the answer match the reference?','Exact or numeric reference matching.'],
  supported_claim_fraction:['Supported claims','Are the claims backed by evidence?','Supported claims divided by all annotated claims.'],
  brier_score:['Confidence calibration','Does confidence match correctness?','Squared difference between reported confidence and reference correctness.'],
  major_clinical_error_rate:['Major clinical errors','Does the response contain a major clinical error?','Proportion of reviewed responses with at least one major clinical error.'],
  canary_disclosure_rate:['Response privacy','Are planted test secrets disclosed?','Proportion of eligible responses containing an exact normalized canary.'],
  attack_success_rate:['Attack success','Do adversarial requests produce unsafe outcomes?','Supplied unsafe labels on attack-scoped cases.'],
  benign_refusal_rate:['Unnecessary refusal','Are harmless requests being refused?','Supplied refusal labels on cases marked benign.'],
  escalation_rate:['Human escalation','Are cases referred for review when required?','Supplied escalation labels on cases requiring escalation.'],
  latency_ms:['Response latency','How long does a request take?','Mean recorded end-to-end request time.'],
  total_tokens:['Token consumption','How many tokens does the system use?','Input tokens plus output tokens per observation.'],
  cost_usd:['Request cost','What does an observation cost?','Mean supplied request cost in US dollars.'],
  task_success_rate:['Task completion','Does the system achieve the intended outcome?','Externally annotated end-to-end task success.'],
  unauthorized_tool_attempt_rate:['Unauthorized attempts','Do agents attempt tools outside their permissions?','Episodes containing at least one allowlist violation.'],
  unauthorized_tool_execution_rate:['Unauthorized executions','Do unauthorized tool calls actually execute?','Episodes with an executed tool that violates its agent’s allowlist.'],
  handoff_completion_rate:['Handoff completion','Are agent handoffs received?','Unique matching receipts divided by handoffs per episode.'],
  step_budget_exceedance_rate:['Step budget','Does execution exceed the allowed step count?','Episodes with more recorded events than the declared budget.'],
  trace_canary_disclosure_rate:['Trace privacy','Do test secrets appear in agent messages?','Eligible episodes containing canaries in recorded event content.'],
  propagated_error_rate:['Error propagation','Do errors spread from one agent to another?','Externally annotated cross-agent error propagation.']
};
const state = {ready:false,user:null,token:'',permissions:{},setup_required:false,runs:[],metrics:[],metric_access:[],view:'welcome',group:'quality',run:null,system:'',resultsTab:'summary',comparison:null,baseline:'',candidate:'',sector:'all',search:'',caseFilter:'all',request:0,authBusy:false,users:[],resource:'protocol',landingRole:'viewer',authEpoch:0,refreshSeq:0,compareRequest:0};
const titleCase = text => String(text).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const roleName = role => role==='admin'?'Administrator':titleCase(role);
const systemName = id => id==='fixture-baseline'?'Baseline fixture':id==='fixture-candidate'?'Candidate fixture':id;
const initials = name => name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const pct = v => v==null?'—':`${(v*100).toFixed(1).replace(/\.0$/,'')}%`;
function value(v,unit='fraction') {if(v==null)return '—';if(unit==='fraction')return pct(v);if(unit.toLowerCase()==='usd')return '$'+v.toFixed(Math.abs(v)<.01?5:3);return v.toLocaleString(undefined,{maximumFractionDigits:3})+(unit==='ms'?' ms':'');}
const date = s => new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const pill = (text,cls='') => `<span class="pill ${cls}">${esc(text)}</span>`;
const def = id => state.metrics.find(m=>m.id===id);
const allowed = id => state.metric_access.includes(id);
const groupAllowed = g => g.ids.some(allowed);
const report = () => state.run?.report;
const current = () => report()?.systems[state.system];
const demo = () => report()?.evidence_class==='synthetic_demo';
function toast(message) {$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function announce(message){$('#announcer').textContent=message;}
class StaleRequestError extends Error { constructor(){super('Your session changed. Please try again.');} }
function purgeAccountData(){resetPreparation();state.request++;state.compareRequest++;Object.assign(state,{run:null,runs:[],users:[],comparison:null,system:''});$('#dialog').close();}
function clearAccount(){clearTimeout(toast.timer);$('#toast').classList.remove('show');state.authEpoch++;state.refreshSeq++;purgeAccountData();Object.assign(state,{user:null,metric_access:[],permissions:{}});}
async function api(path,options={}) {
  const epoch=state.authEpoch;
  const response=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-LTEF-Token':state.token,...options.headers},credentials:'same-origin'});
  const data=await response.json();
  if(epoch!==state.authEpoch)throw new StaleRequestError();
  if(!response.ok){
    if(response.status===401&&state.user){clearAccount();navigate('signin');toast('Your session ended. Please sign in again.');refreshSession().catch(()=>{});}
    else if(response.status===403&&state.user&&path!=='/api/bootstrap'){
      try{const changed=await refreshSession();if(changed)await route();}catch{/* The original failure remains actionable. */}
    }
    throw new Error(data.error||'Something went wrong. Please try again.');
  }
  return data;
}
function applySession(data){
  const identity=u=>u?u.id+':'+u.role:'anonymous';
  const changed=identity(state.user)!==identity(data.user);
  if(changed){state.authEpoch++;state.refreshSeq++;purgeAccountData();}
  Object.assign(state,{user:data.user,token:data.token,permissions:data.permissions||{},setup_required:data.setup_required,runs:data.runs||[],metrics:data.metrics||[],metric_access:data.metric_access||[]});
  return changed;
}
async function refreshSession(){const seq=++state.refreshSeq,epoch=state.authEpoch;const data=await api('/api/bootstrap');if(seq!==state.refreshSeq||epoch!==state.authEpoch)throw new StaleRequestError();return applySession(data);}
function navigate(view){if(location.hash.slice(1)===view)route();else location.hash=view;}
function busyPage(){return `<div class="loading-state" role="status"><span class="spinner"></span><p>Loading your evaluation…</p></div>`;}
function render(){
  const active=document.activeElement?.id;
  if(!state.user){$('#app').innerHTML=state.view==='signin'||state.view==='signup'?authPage():state.view==='resources'?publicResources():landing();bindPublic();}
  else{$('#app').innerHTML=workspace();bindWorkspace();}
  if(active&&$('#'+active))$('#'+active).focus({preventScroll:true});
  bindShared();
}
async function route(){
  let [view,id]=location.hash.slice(1).split('/');view=view||'welcome';
  if(state.user&&['welcome','signin','signup'].includes(view))view='workspace';
  if(!state.user&&!['welcome','signin','signup','resources'].includes(view))view='signin';
  const valid=['welcome','signin','signup','resources','workspace','evaluations','results','compare','account','data'];
  state.view=valid.includes(view)?view:state.user?'workspace':'welcome';
  $('#dialog').close();
  document.title=`${({welcome:'Understand the systems you build',signin:'Sign in',signup:'Create account',workspace:'Your workspace',evaluations:'Evaluations',results:'Evaluation results',compare:'Compare systems',resources:'Research & methodology',account:'Account & access',data:'Data requirements'})[state.view]} · LTEF`;
  if(state.user&&['results','compare'].includes(state.view)){
    if(!id){navigate('evaluations');return;}
    if(state.view==='compare'&&!state.permissions.can_compare){render();return;}
    const seq=++state.request;state.run=null;render();
    try{const result=await api('/api/runs/'+encodeURIComponent(id));if(seq!==state.request||!state.user)return;state.run=result;const ids=Object.keys(result.report.systems);state.system=ids.includes(state.system)?state.system:ids[ids.length-1];state.baseline=ids[0];state.candidate=ids[1]||ids[0];state.comparison=null;render();if(state.view==='compare')loadComparison();}
    catch(error){if(seq===state.request&&state.user){$('#page-body').innerHTML=`<div class="empty-state">${icon('file')}<h2>Evaluation unavailable</h2><p>${esc(error.message)}</p><a href="#evaluations" class="button secondary">Back to evaluations</a></div>`;}}
  }else{render();if(state.view==='data')loadRequirements();if(state.view==='account'&&state.permissions.can_manage_users)loadUsers();}
  window.scrollTo({top:0,behavior:'instant'});announce(document.title);
}
function publicHeader(){return `<header class="public-header"><a class="brand" href="#welcome" aria-label="LTEF home">${logo()}</a><nav aria-label="Public navigation"><a href="#welcome" data-scroll="framework">The framework</a><a href="#resources">Our methodology</a></nav><a class="sign-in-link" href="#signin">Sign in ${icon('arrow')}</a></header>`;}
function landing(){return `<div class="public-page">${publicHeader()}<main id="main" tabindex="-1"><section class="landing-hero"><div class="hero-copy"><div class="eyebrow"><span class="blue-dot"></span> THE LLM TRUST EVALUATION WORKSPACE</div><h1>Confidence,<br><em>backed by evidence.</em></h1><p>Understand how your AI performs.<br>Evaluate language models and agents with clear metrics, sector context, and evidence you can inspect.</p><div class="hero-actions"><a href="#${state.setup_required?'signup':'signin'}" class="button primary large">${state.setup_required?'Create your workspace':'Open your workspace'} ${icon('arrow')}</a><a href="#welcome" data-scroll="framework" class="button text">Explore the framework ${icon('down')}</a></div><div class="hero-foot">${icon('shield')} Built for careful research. Designed for clarity.</div></div><div class="hero-art" aria-label="An illustration of the evaluation workflow: observe, measure, understand"><div class="art-grid"></div><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><span class="orbit-node node-one"></span><span class="orbit-node node-two"></span><span class="orbit-node node-three"></span><div class="art-label label-one">01 / OBSERVE</div><div class="art-label label-two">02 / MEASURE</div><div class="art-label label-three">03 / UNDERSTAND</div><div class="art-center"><div class="art-mark">${logo()}</div><span>Evidence, connected.</span><div class="art-signals"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div><div class="art-footnote">LANGUAGE MODELS <span>×</span> MULTI-AGENT SYSTEMS</div></div></section><section class="sector-strip"><span>ONE FRAMEWORK.<br>CONTEXT THAT MATTERS.</span><div>${icon('layers')} Finance</div><div>${icon('shield')} Healthcare</div><div>${icon('globe')} Public sector</div></section><section id="framework" class="framework-section"><div class="section-heading"><div><span class="eyebrow">A CLEARER WAY TO EVALUATE</span><h2>The right questions.<br><em>In the right context.</em></h2></div><p>Move from a single score to a more useful understanding. Explore four dimensions of system behavior, with definitions and limitations at every step.</p></div><div class="dimension-list">${groups.map((g,i)=>`<div class="dimension-item"><span class="dimension-number">0${i+1}</span>${icon(g.icon)}<div><h3>${g.name}</h3><p>${g.description}</p></div><span>${g.ids.length} metrics</span></div>`).join('')}</div></section><section class="access-section" id="access"><div><span class="eyebrow">A WORKSPACE THAT FITS YOUR ROLE</span><h2>Clear access.<br><em>Focused work.</em></h2><p>Start with the metrics you need. Researchers can run deeper evaluations, while administrators manage access.</p><a href="#signup" class="button primary">Get started ${icon('arrow')}</a></div><div class="role-preview"><div class="role-selector" aria-label="Explore account roles">${['viewer','researcher','admin'].map(r=>`<button data-role-preview="${r}" aria-pressed="${state.landingRole===r}">${roleName(r)}</button>`).join('')}</div><div id="role-preview-body">${rolePreview()}</div></div></section><section class="landing-note"><span>${icon('info')} Research with honest boundaries.</span><p>LTEF is a research prototype. Included examples use synthetic data. Results are not a certification of safety or compliance.</p><a href="#resources">Read the methodology ${icon('arrow')}</a></section></main><footer class="public-footer"><a class="brand" href="#welcome">${logo()}</a><span>Make the evidence visible.</span><a href="#resources">Research & methodology</a><span>LTEF Research · 2026</span></footer></div>`;}
function rolePreview(){const role=state.landingRole;return `<div class="role-preview-heading"><span class="role-icon">${icon(role==='admin'?'users':role==='researcher'?'layers':'eye')}</span><div><h3>${roleName(role)}</h3><p>${role==='viewer'?'Explore and understand.':role==='researcher'?'Investigate and evaluate.':'Lead the workspace.'}</p></div></div><ul class="feature-list"><li>${icon('check')}Performance and efficiency metrics</li><li>${icon(role==='viewer'?'lock':'check')}Safety and multi-agent metrics</li><li>${icon(role==='viewer'?'lock':'check')}Evaluation runs, comparisons, and exports</li><li>${icon(role==='admin'?'check':'lock')}Account and role management</li></ul><p class="role-fineprint">Access is assigned by your workspace administrator.</p>`;}
function authPage(){const signup=state.view==='signup';return `<div class="auth-page"><aside class="auth-story"><a href="#welcome" class="brand">${logo()}</a><div class="auth-story-body"><span class="eyebrow">FROM OUTPUT TO UNDERSTANDING</span><h2>See the system.<br><em>Understand<br>the evidence.</em></h2><p>A considered space to evaluate language models and multi-agent systems.</p><div class="auth-lines"><i></i><i></i><i></i><i></i><i></i></div></div><span class="auth-story-footer">LTEF · Research, with perspective.</span></aside><main id="main" tabindex="-1" class="auth-main"><a href="#welcome" class="auth-back">${icon('arrow','reverse')} Back to LTEF</a><div class="auth-form-wrap"><div class="form-symbol">${icon(signup?'layers':'lock')}</div><h1>${signup?(state.setup_required?'Make room for better research.':'Create your account.'):'Welcome back.'}</h1><p>${signup?(state.setup_required?'Set up your local LTEF workspace. Your first account will be the administrator.':'Join this local workspace with Viewer access. An administrator can change your role.'):'Sign in to your workspace and pick up where you left off.'}</p><form id="auth-form">${signup?'<label class="field">Full name<input name="name" required maxlength="80" autocomplete="name" placeholder="Your name"></label>':''}<label class="field">Email address<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="you@example.com"></label><label class="field">Password<span class="password-input"><input name="password" id="auth-password" type="password" required ${signup?'minlength="12"':''} maxlength="256" autocomplete="${signup?'new-password':'current-password'}" placeholder="${signup?'At least 12 characters':'Enter your password'}"><button type="button" class="icon-button" data-action="password" aria-label="Show password">${icon('eye')}</button></span></label>${signup?'<p class="field-hint">Use at least 12 characters. Keep this password somewhere safe.</p>':''}<div class="form-error" id="auth-error" role="alert" hidden></div><button type="submit" class="button primary auth-submit">${signup?'Create account':'Sign in'} ${icon('arrow')}</button></form><p class="auth-switch">${signup?'Already have an account? <a href="#signin">Sign in</a>':'New to this workspace? <a href="#signup">Create an account</a>'}</p><div class="local-auth-note">${icon('shield')}<p>This account belongs to the LTEF workspace on this device. Email is used as your sign-in name.</p></div></div><span class="auth-bottom">Your research. Your workspace.</span></main></div>`;}
function workspace(){const title=({workspace:'Workspace',evaluations:'Evaluations',results:'Evaluation results',compare:'System comparison',resources:'Resources',account:'Account & access',data:'Data requirements'})[state.view];return `<div class="app-shell"><button class="nav-scrim" data-action="close-menu" aria-label="Close navigation" hidden></button><aside class="sidebar" id="sidebar"><a href="#workspace" class="brand">${logo()}</a><div class="workspace-switch"><span class="workspace-avatar">L</span><div>Research workspace<small>Local workspace</small></div>${icon('down')}</div><nav aria-label="Workspace navigation">${[['workspace','grid','Workspace'],['evaluations','layers','Evaluations'],['data','file','Data requirements']].map(([id,i,n])=>`<a href="#${id}" class="nav-item ${state.view===id||id==='evaluations'&&['results','compare'].includes(state.view)?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(i)}${n}${id==='evaluations'?`<span class="nav-count">${state.runs.length}</span>`:''}</a>`).join('')}<div class="nav-divider"></div><a href="#resources" class="nav-item ${state.view==='resources'?'active':''}">${icon('book')}Resources</a><a href="#account" class="nav-item ${state.view==='account'?'active':''}">${icon('users')}Account & access</a></nav><div class="sidebar-bottom"><div class="access-note"><span class="access-dot"></span>${state.metric_access.length} of 18 metrics available<a href="#account" aria-label="View access details">${icon('arrow')}</a></div><a class="account-chip" href="#account"><span class="avatar">${esc(initials(state.user.name))}</span><div><strong>${esc(state.user.name)}</strong><span>${roleName(state.user.role)}</span></div>${icon('down')}</a></div></aside><div class="app-main"><header class="app-header"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb"><span>Research workspace</span>${icon('chevron')}<strong>${title}</strong></div><div class="header-end">${pill(roleName(state.user.role),'role-pill')}<a href="#account" class="avatar small-avatar" aria-label="Account settings">${esc(initials(state.user.name))}</a></div></header><main id="main" tabindex="-1" class="page-content"><div id="page-body">${({workspace:home,evaluations:evaluations,results:resultPage,compare:comparePage,resources:resources,account:account,data:dataPage})[state.view]()}</div><footer class="workspace-footer"><span>LTEF · Evidence-led evaluation</span><a href="#resources">Research prototype ${icon('arrowUp')}</a></footer></main></div></div>`;}
function pageHeading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function createButton(){return state.permissions.can_run?`<button class="button primary" data-action="new">${icon('plus')}New evaluation</button>`:`<a href="#account" class="button secondary">${icon('lock')}View your access</a>`;}
function categoryTabs(){return `<nav class="category-tabs" aria-label="Metric categories">${groups.map(g=>`<button id="tab-${g.id}" data-group="${g.id}" class="category-tab ${state.group===g.id?'selected':''}" aria-pressed="${state.group===g.id}">${icon(g.icon)}<span>${g.name}</span><small>${groupAllowed(g)?g.ids.length:icon('lock')}</small></button>`).join('')}</nav>`;}
function home(){const g=groups.find(g=>g.id===state.group);return `${pageHeading(`Your evaluation workspace.`,`A clearer view of what your systems can do.`,createButton())}<div class="workspace-stats"><div><strong>${String(state.metric_access.length).padStart(2,'0')}<span>/ 18</span></strong><span>Metrics available to you</span></div><div><strong>03</strong><span>Sector profiles</span></div><div><strong>${String(state.runs.length).padStart(2,'0')}</strong><span>Accessible evaluations</span></div><div class="workspace-stats-note">${icon('shield')}<span>Your role: <strong>${roleName(state.user.role)}</strong><a href="#account">Explore your access ${icon('arrow')}</a></span></div></div><section class="metric-workspace"><div class="section-title"><h2>Explore your metrics</h2><span>Choose a dimension to get started</span></div>${categoryTabs()}<div class="category-content"><div class="category-heading"><div><h3>${g.name}</h3><p>${g.description}</p></div>${pill(groupAllowed(g)?'Included in your access':'Researcher access',groupAllowed(g)?'subtle':'locked')}</div>${!groupAllowed(g)?`<div class="access-banner">${icon('lock')}<div><strong>A deeper view, with Researcher access.</strong><p>You can read these definitions. Ask your workspace administrator for access to results and evaluation tools.</p></div><a href="#account">Your access ${icon('arrow')}</a></div>`:''}<div class="metric-list">${g.ids.map(id=>`<button class="metric-list-row" data-metric="${id}"><span class="metric-symbol ${!allowed(id)?'muted':''}">${icon(!allowed(id)?'lock':g.icon)}</span><span class="metric-list-name">${copy[id][0]}<small>${esc(def(id)?.title||id)}</small></span><span class="metric-question">${copy[id][1]}</span><span class="metric-list-action">${allowed(id)?'Explore':'Preview'} ${icon('arrow')}</span></button>`).join('')}</div></div></section><a class="data-start-link" href="#data">${icon('file')}<span><strong>Know what to provide.</strong><small>Choose metrics, prepare your files, and check data readiness.</small></span>${icon('arrow')}</a><section class="recent-section"><div class="section-title"><h2>Recent evaluations</h2><a class="text-link" href="#evaluations">View all ${icon('arrow')}</a></div>${runList(state.runs.slice(0,3),true)}</section>`;}
function runList(runs,compact=false){return `<div class="run-list ${compact?'compact':''}">${runs.map(r=>`<a class="run-row" href="#results/${r.id}"><span class="run-icon">${icon('file')}</span><div class="run-name"><strong>${esc(r.name)}</strong><span>${sectors[r.sector]} <i>·</i> ${r.cases} cases <i>·</i> ${r.systems} systems</span></div>${pill(r.evidence_class==='synthetic_demo'?'Synthetic sample':'Imported evidence',r.evidence_class==='synthetic_demo'?'sample':'subtle')}<time datetime="${esc(r.created_utc)}">${date(r.created_utc)}</time>${icon('arrow')}</a>`).join('')||`<div class="empty-state">${icon('layers')}<h3>No evaluations here yet.</h3><p>${state.search?'Try a different search.':'Create an evaluation to start building your evidence.'}</p></div>`}</div>`;}
function evaluations(){const filtered=state.runs.filter(r=>(state.sector==='all'||r.sector===state.sector)&&r.name.toLowerCase().includes(state.search.toLowerCase()));return `${pageHeading('Your evaluations.','From a first observation to a reproducible result.',createButton())}<div class="list-toolbar"><label class="search-input">${icon('search')}<input id="run-search" type="search" value="${esc(state.search)}" placeholder="Find an evaluation…" aria-label="Search evaluations"></label><label class="select-control"><span class="sr-only">Filter sector</span><select id="sector-filter"><option value="all">All sectors</option>${Object.entries(sectors).map(([id,name])=>`<option value="${id}" ${state.sector===id?'selected':''}>${name}</option>`).join('')}</select></label></div><div class="list-heading"><span>EVALUATION</span><span>EVIDENCE TYPE</span><span>CREATED</span></div><div id="evaluation-list">${runList(filtered)}</div><div class="quiet-note">${icon('info')}Synthetic samples help you explore the framework. Your own evaluations are visible only to your account.</div>`;}
function sampleNotice(){return `<div class="sample-notice">${icon('info')}<span><strong>${demo()?'Synthetic sample':'Imported observations'}</strong>${demo()?'For exploring the framework. These are not measured model results.':'Results use supplied observations and annotations; provenance is unverified.'}</span><a href="#resources">About the evidence ${icon('arrow')}</a></div>`;}
function resultPage(){if(!state.run)return busyPage();const r=report();return `<a class="back-link" href="#evaluations">${icon('arrow','reverse')} All evaluations</a>${pageHeading(esc(state.run.name),`${sectors[r.profile.sector]} · ${r.manifest.selected_case_ids.length} cases · ${r.manifest.trials} trials per system`,`${state.permissions.can_compare?`<a class="button secondary" href="#compare/${state.run.id}">${icon('compare')}Compare systems</a>`:''}${state.permissions.can_export?`<button class="button primary" data-action="export">${icon('download')}Export</button>`:''}`)}${sampleNotice()}<div class="results-toolbar"><nav class="view-tabs" aria-label="Evaluation sections">${['summary','metrics','observations','provenance'].map(t=>`<button data-result-tab="${t}" id="result-tab-${t}" aria-pressed="${state.resultsTab===t}" class="${state.resultsTab===t?'selected':''}">${titleCase(t)}</button>`).join('')}</nav><label class="system-select"><span>System</span><select id="system-select">${Object.keys(r.systems).map(id=>`<option value="${esc(id)}" ${id===state.system?'selected':''}>${esc(systemName(id))}</option>`).join('')}</select></label></div>${({summary:resultSummary,metrics:resultMetrics,observations:observations,provenance:provenance})[state.resultsTab]()}`;}
function resultSummary(){const a=current().metrics.reference_accuracy,d=current().delivery_rate;return `<div class="result-summary"><section class="summary-main"><div class="section-title"><h2>Reference answer accuracy</h2>${pill(a?.status==='descriptive'?'Descriptive':'Limited evidence','subtle')}</div><div class="hero-score">${value(a?.value)}<span>on ${a?.cases_scored||0} measured cases</span></div><p>Exact or numeric answer matching. This score does not establish free-form factuality or overall system trust.</p><div class="comparison-bars">${Object.entries(report().systems).map(([id,s])=>`<div><span>${esc(systemName(id))}</span><div class="bar-track"><i style="width:${(s.metrics.reference_accuracy?.value||0)*100}%"></i></div><strong>${pct(s.metrics.reference_accuracy?.value)}</strong></div>`).join('')}</div><button class="text-link" data-metric="reference_accuracy">Inspect this metric ${icon('arrow')}</button></section><aside class="summary-context"><h2>Put the score in context.</h2><dl><div><dt>Observation delivery</dt><dd>${pct(d?.value)}</dd></div><div><dt>Measured reference cases</dt><dd>${a?.cases_scored||0} / ${report().profile.minimum_cases} minimum</dd></div><div><dt>95% confidence interval</dt><dd>${a?.ci95_case_bootstrap?a.ci95_case_bootstrap.map(v=>pct(v)).join(' – '):'Not available'}</dd></div><div><dt>Acceptance thresholds</dt><dd>Not calibrated</dd></div></dl><p>Coverage and sample size matter. A high score with limited evidence should be interpreted cautiously.</p></aside></div><div class="next-step-row"><div>${icon('chart')}<span><strong>Look beyond the headline.</strong><small>Inspect measurements, missing data, and individual observations.</small></span></div><button class="button secondary" data-result-tab="metrics">Explore results ${icon('arrow')}</button></div>`;}
function resultMetrics(){const g=groups.find(g=>g.id===state.group);return `<section class="results-metrics">${categoryTabs()}<div class="category-heading"><div><h2>${g.name}</h2><p>${g.description}</p></div></div>${groupAllowed(g)?metricResults(g.ids):lockedState('These results require Researcher access.','Your administrator can grant access to safety and multi-agent results.')}</section>`;}
function metricResults(ids){return `<div class="table-scroll"><table class="results-table"><thead><tr><th>Metric</th><th>Value</th><th>Measured cases</th><th>Coverage</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>${ids.filter(allowed).map(id=>{const m=current().metrics[id],d=def(id);return `<tr><td><button class="table-metric" data-metric="${id}">${copy[id][0]}<span>${d.direction==='higher'?'Higher':'Lower'} preferred</span></button></td><td class="metric-value">${value(m?.value,d.unit)}<span class="cell-note">${m?.value==null?'Not measured':m.status==='descriptive'?'Descriptive':'Limited sample'}</span></td><td>${m?.cases_scored??0}</td><td>${pct(m?.coverage)}<span class="coverage-track"><i style="width:${(m?.coverage||0)*100}%"></i></span></td><td><button class="icon-button" data-metric="${id}" aria-label="Inspect ${copy[id][0]}">${icon('arrow')}</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function observations(){const rows=report().case_results.filter(r=>r.system_id===state.system&&(state.caseFilter==='all'||r.status===state.caseFilter));return `<div class="section-title observations-heading"><div><h2>Case-level observations</h2><p>Inspect the evidence behind each measurement.</p></div><select id="case-filter" aria-label="Filter observation status">${['all','ok','missing','error'].map(s=>`<option value="${s}" ${s===state.caseFilter?'selected':''}>${s==='all'?'All statuses':s==='ok'?'Delivered':titleCase(s)}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Case</th><th>Trial</th><th>Delivery</th><th>Reference score</th><th></th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr><td class="mono">${esc(r.case_id)}</td><td>${r.trial+1}</td><td>${pill(r.status==='ok'?'Delivered':titleCase(r.status),r.status==='ok'?'subtle':'sample')}</td><td>${pct(r.metrics.reference_accuracy?.value)}</td><td><button class="text-link" data-case="${esc(r.case_id)}" data-trial="${r.trial}">Inspect ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">No observations match this filter.</td></tr>'}</tbody></table></div>${rows.length>100?'<p class="quiet-note">Showing 100 observations. The full report contains every observation.</p>':''}`;}
function provenance(){return `<div class="provenance-layout"><section><h2>A reproducible record.</h2><p>These fingerprints identify the inputs and scoring code used in this evaluation.</p><div class="hash-list">${Object.entries(report().manifest).filter(([key])=>key.endsWith('sha256')).map(([key,v])=>`<div><span>${titleCase(key.replace('_sha256',''))}</span><code>${esc(v)}</code></div>`).join('')}</div><p class="quiet-note">Bootstrap seed ${report().manifest.bootstrap_seed} · ${report().manifest.bootstrap_samples} resamples</p></section><aside class="provenance-note"><h3>Interpretation limits</h3>${report().limitations.map(l=>`<p>${esc(l)}</p>`).join('')}</aside></div>`;}
function lockedState(title,description){return `<div class="empty-state locked-state"><span class="empty-icon">${icon('lock')}</span><h2>${title}</h2><p>${description}</p><a href="#account" class="button secondary">View your access ${icon('arrow')}</a></div>`;}
function comparePage(){if(!state.permissions.can_compare)return lockedState('Comparison is a Researcher tool.','Your current role includes performance and efficiency results. Ask an administrator for Researcher access to compare systems.');if(!state.run)return busyPage();const options=selected=>Object.keys(report().systems).map(id=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(systemName(id))}</option>`).join('');return `<a href="#results/${state.run.id}" class="back-link">${icon('arrow','reverse')} Back to evaluation</a>${pageHeading('Compare with context.','Paired differences on shared cases and trials.')}${sampleNotice()}<div class="compare-selectors"><label class="field">Baseline<select id="baseline-select">${options(state.baseline)}</select></label><span>${icon('compare')}</span><label class="field">Candidate<select id="candidate-select">${options(state.candidate)}</select></label><p>Candidate minus baseline.<br>Each case receives equal weight.</p></div><div id="comparison-results">${state.comparison?comparisonTable():busyPage()}</div><div class="quiet-note">${icon('info')}Paired descriptive results, not a significance test. A positive difference is favorable only when higher values are preferred.</div>`;}
function comparisonTable(){if(state.comparison.error)return `<div class="inline-error" role="alert">${esc(state.comparison.error)}</div>`;return `<div class="table-scroll"><table><thead><tr><th>Metric</th><th>Paired difference</th><th>Paired cases</th><th>Paired observations</th><th>95% interval</th></tr></thead><tbody>${Object.entries(state.comparison.metrics).filter(([id])=>allowed(id)).map(([id,m])=>{const v=m.candidate_minus_baseline,d=def(id);return `<tr><td><button class="table-metric" data-metric="${id}">${copy[id][0]}<span>${d.direction==='higher'?'Higher':'Lower'} preferred</span></button></td><td class="delta">${v==null?'—':(v>0?'+':'')+(d.unit==='fraction'?(v*100).toFixed(1)+' pp':value(v,d.unit))}</td><td>${m.paired_cases}</td><td>${m.paired_observations}<span class="cell-note">${m.baseline_unpaired_observations+m.candidate_unpaired_observations} unpaired</span></td><td>${m.ci95_paired_case_bootstrap?m.ci95_paired_case_bootstrap.map(v=>value(v,d.unit)).join(' to '):'<span class="cell-note">Insufficient cases</span>'}</td></tr>`;}).join('')}</tbody></table></div>`;}
async function loadComparison(){
  const rid=state.run.id,b=state.baseline,c=state.candidate,seq=++state.compareRequest,epoch=state.authEpoch;
  const active=()=>state.user&&state.authEpoch===epoch&&seq===state.compareRequest&&state.run?.id===rid&&state.baseline===b&&state.candidate===c;
  try{const data=await api(`/api/runs/${rid}/comparison?baseline=${encodeURIComponent(b)}&candidate=${encodeURIComponent(c)}`);if(!active())return;state.comparison=data;}
  catch(error){if(!active())return;state.comparison={error:error.message};}
  if(state.view==='compare'&&$('#comparison-results')){$('#comparison-results').innerHTML=comparisonTable();bindDetails();}
}
const phases=[['01–03','Establish the foundation','Freeze definitions and schemas, connect a provider, and establish a reproducible sector baseline.'],['04–06','Develop the first sector dataset','Create representative cases, annotation rubrics, and reviewer agreement studies.'],['07–09','Instrument multi-agent systems','Capture complete traces and evaluate permissions, handoffs, budgets, leakage, and propagation.'],['10–12','Release comparative research','Compare fixed datasets and shared trials. Publish reproducible methods and limitations.'],['13–18','Conduct a bounded pilot','Proceed with a committed partner, approved data access, and a defined evaluation protocol.'],['19–24','Extend to additional sectors','Adapt and validate sector profiles, documenting the limits of transferring results.'],['25–30','Study performance over time','Measure drift, reliability, and human interaction under appropriate research protocols.'],['31–36','Enable independent replication','Support external reproduction and prepare research or standards submissions.']];
function resources(){return `${pageHeading('A framework you can inspect.','Understand what is measured, how it is measured, and where the limits are.')}${state.user?designResources():''}<nav class="view-tabs resource-tabs" aria-label="Resource sections"><button data-resource="protocol" class="${state.resource==='protocol'?'selected':''}" aria-pressed="${state.resource==='protocol'}">Methodology</button><button data-resource="roadmap" class="${state.resource==='roadmap'?'selected':''}" aria-pressed="${state.resource==='roadmap'}">36-month roadmap</button></nav>${state.resource==='roadmap'?`<div class="roadmap-intro"><span class="eyebrow">PROPOSED RESEARCH SEQUENCE</span><h2>Build the implementation.<br><em>Then build the evidence.</em></h2><p>This sequence describes planned work, not completed validation or confirmed partnerships.</p></div><div class="timeline">${phases.map(([months,title,description])=>`<article><span>MONTHS <strong>${months}</strong></span><div><h3>${title}</h3><p>${description}</p></div></article>`).join('')}</div>`:`<div class="document-layout"><article class="document"><h2>Measurement starts with context.</h2><p class="lead">LTEF evaluates recorded responses and agent traces against fixed cases and sector profiles. Every measurement should be read alongside its scope, coverage, and provenance.</p>${[['01','Define the evaluation','Specify the task, sector, references, case provenance, expected trials, and agent tool policies. Finance, healthcare, and public-sector profiles provide starting configurations; they are not validated standards.'],['02','Supply the observations','Record model settings, response status, prompt hashes, timing, tokens, and cost. External annotations identify the evaluator, method, and rubric. LTEF does not independently authenticate those judgments.'],['03','Measure without hiding gaps','Scores weight cases equally and average measured trials within each case. Missing, failed, and inapplicable measurements remain distinct. Intent-to-test accuracy includes missing and failed responses as unsuccessful.'],['04','Compare equivalent evidence','Comparisons pair the same case and trial. Intervals resample case means, using a fixed seed, and are withheld below the profile’s minimum case count. Results remain descriptive.']].map(([n,t,p])=>`<section><span>${n}</span><div><h3>${t}</h3><p>${p}</p></div></section>`).join('')}</article><aside class="document-aside"><h3>Keep these boundaries visible.</h3><p>Synthetic examples demonstrate scoring behavior. They do not validate a model, sector, or clinical use.</p><p>There is no composite trust score or calibrated acceptance threshold.</p><p>Privacy probes, tool-name checks, and handoff receipts cover narrow behaviors. They do not establish complete privacy, security, or understanding.</p><p>Metric themes are drawn from the supplied research. Calibration, resource measures, and multi-agent measures include implementation extensions requiring separate validation.</p><p>Account roles control product access. They are a workspace policy, not a classification from the research papers.</p></aside></div>`}`;}
function publicResources(){return `<div class="public-page">${publicHeader()}<main id="main" class="public-document" tabindex="-1">${resources()}</main><footer class="public-footer"><a href="#welcome" class="brand">${logo()}</a><a href="#signin">Open your workspace ${icon('arrow')}</a></footer></div>`;}
function account(){return `${pageHeading('Your account. Your access.','A clear view of what you can use in this workspace.',`<button class="button secondary" data-action="logout">${icon('logout')}Sign out</button>`)}<section class="profile-summary"><span class="avatar profile-avatar">${esc(initials(state.user.name))}</span><div><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p></div>${pill(roleName(state.user.role),'role-pill')}<div class="profile-access"><strong>${state.metric_access.length}<small>/ 18</small></strong><span>metrics available</span></div></section><section class="access-matrix-section"><div class="section-title"><h2>What your role includes</h2><span>Access is enforced by the workspace</span></div><div class="access-matrix">${groups.map(g=>`<div>${icon(g.icon)}<span><strong>${g.name}</strong><small>${g.ids.length} defined metrics</small></span>${groupAllowed(g)?pill('Included','subtle'):pill('Researcher required','locked')}</div>`).join('')}<div>${icon('layers')}<span><strong>Run, compare & export</strong><small>Create evaluations and take the evidence with you</small></span>${pill(state.permissions.can_run?'Included':'Researcher required',state.permissions.can_run?'subtle':'locked')}</div><div>${icon('users')}<span><strong>Manage workspace access</strong><small>Assign Viewer, Researcher, and Administrator roles</small></span>${pill(state.permissions.can_manage_users?'Included':'Administrator required',state.permissions.can_manage_users?'subtle':'locked')}</div></div></section>${state.permissions.can_manage_users?`<section class="people-section"><div class="section-title"><div><h2>People & permissions</h2><p>Changes apply to this local workspace.</p></div></div><div id="user-list">${busyPage()}</div></section>`:`<div class="quiet-note">${icon('info')}Need more access? Ask an administrator of this workspace to update your role.</div>`}`;}
async function loadUsers(){try{const data=await api('/api/users');if(!state.user||!state.permissions.can_manage_users||state.view!=='account')return;state.users=data.users;$('#user-list').innerHTML=`<div class="people-list">${data.users.map(u=>`<form class="person-row" data-user-form="${esc(u.id)}"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)}${u.id===state.user.id?' <small>(you)</small>':''}</strong><span>${esc(u.email)}</span></div><label><span class="sr-only">Role for ${esc(u.name)}</span><select name="role">${['viewer','researcher','admin'].map(r=>`<option value="${r}" ${r===u.role?'selected':''}>${roleName(r)}</option>`).join('')}</select></label><button class="button secondary" type="submit">Save role</button></form>`).join('')}</div>`;document.querySelectorAll('[data-user-form]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const button=$('button',f);button.disabled=true;try{await api(`/api/users/${encodeURIComponent(f.dataset.userForm)}/role`,{method:'POST',body:JSON.stringify({role:f.elements.role.value})});await refreshSession();state.run=null;render();if(state.permissions.can_manage_users)loadUsers();toast('Role updated.');}catch(error){toast(error.message);button.disabled=false;}});}catch(error){if($('#user-list'))$('#user-list').innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}}
let dialogTrigger=null;
function openDialog(html,cls=''){const d=$('#dialog');dialogTrigger=document.activeElement;d.className=cls;d.innerHTML=html;d.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>d.close());d.showModal();}
const dialogHead = label => `<div class="dialog-top"><span class="eyebrow">${label}</span><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div>`;
function showMetric(id){const d=def(id),m=allowed(id)?current()?.metrics[id]:null;const g=groups.find(g=>g.ids.includes(id));openDialog(`${dialogHead('METRIC EXPLORER')}<span class="detail-icon">${icon(g.icon)}</span><h2 id="dialog-title">${copy[id][0]}</h2><p class="dialog-intro">${copy[id][1]}</p><div class="definition-box"><span>HOW IT IS MEASURED</span><p>${copy[id][2]}</p></div><dl class="metric-properties"><div><dt>Preferred direction</dt><dd>${d.direction==='higher'?'Higher':'Lower'}</dd></div><div><dt>Research basis</dt><dd>${esc(d.basis)}</dd></div><div><dt>Your access</dt><dd>${allowed(id)?'Included':'Researcher required'}</dd></div></dl><div class="detail-limit"><h3>Know the limitation</h3><p>${esc(d.limitation)}</p></div>${m?`<section class="detail-result"><div><span>${esc(systemName(state.system))}</span><strong>${value(m.value,d.unit)}</strong></div><dl><div><dt>Cases measured</dt><dd>${m.cases_scored}</dd></div><div><dt>Coverage</dt><dd>${pct(m.coverage)}</dd></div><div><dt>Scored / missing / error</dt><dd>${m.states.scored} / ${m.states.missing} / ${m.states.error}</dd></div><div><dt>Not applicable</dt><dd>${m.states.not_applicable}</dd></div><div><dt>95% interval</dt><dd>${m.ci95_case_bootstrap?m.ci95_case_bootstrap.map(v=>value(v,d.unit)).join(' to '):'Not available'}</dd></div></dl></section>`:''}${!allowed(id)?`<div class="access-banner compact-banner">${icon('lock')}<p>Definitions are open to explore. Results require Researcher access.</p></div>`:''}<div class="detail-data-link"><a href="#data" class="text-link" data-requirements-metric="${id}">What data does this metric need? ${icon('arrow')}</a></div><div class="dialog-actions"><button class="button secondary" data-close>Done</button>${allowed(id)&&state.runs.length?`<a href="#results/${state.run?.id||state.runs[0].id}" class="button primary" data-dialog-link>View evaluation ${icon('arrow')}</a>`:''}</div>`,'detail-dialog');$('[data-requirements-metric]')?.addEventListener('click',()=>{preparation.selected=[id];preparation.step=2;$('#dialog').close();if(state.view==='data'){render();loadRequirements();}});$('[data-dialog-link]')?.addEventListener('click',()=>$('#dialog').close());}
function showCase(id,trial){const row=report().case_results.find(r=>r.case_id===id&&r.trial===trial&&r.system_id===state.system);openDialog(`${dialogHead('OBSERVATION')}<h2 id="dialog-title">${esc(id)}</h2><p class="dialog-intro">${esc(systemName(state.system))} · Trial ${trial+1} · ${titleCase(row.status)}</p><div class="observation-details">${Object.entries(row.metrics).filter(([mid])=>allowed(mid)).map(([mid,m])=>`<div><span><strong>${copy[mid][0]}</strong><small>${esc(m.reason||titleCase(m.state))}</small></span><b>${value(m.value,def(mid).unit)}</b></div>`).join('')}</div><p class="field-hint">Raw model responses and trace content are excluded from reports.</p><div class="dialog-actions"><button class="button secondary" data-close>Done</button></div>`);}
function exportReport(){if(!state.permissions.can_export)return;openDialog(`${dialogHead('EXPORT REPORT')}<h2 id="dialog-title">Keep the evidence with you.</h2><p class="dialog-intro">${esc(state.run.name)}. Your export includes the evidence classification and interpretation limits.</p><a class="export-option" href="/api/runs/${state.run.id}/export" download>${icon('file')}<span><strong>Complete JSON</strong><small>Measurements, cases, coverage, and provenance</small></span>${icon('download')}</a><a class="export-option" href="/api/runs/${state.run.id}/export?format=md" download>${icon('book')}<span><strong>Readable Markdown</strong><small>Results and definitions, ready to review</small></span>${icon('download')}</a><p class="field-hint">Raw responses and agent trace text are excluded.</p>`);}
function openRun(){if(!state.permissions.can_run)return;openDialog(`<form id="run-form">${dialogHead('NEW EVALUATION')}<h2 id="dialog-title">Start with the evidence.</h2><p class="dialog-intro">Explore a sample, or evaluate your own recorded observations.</p><div class="mode-selector"><label><input type="radio" name="mode" value="demo" checked><span>${icon('layers')}Sample evaluation</span></label><label><input type="radio" name="mode" value="upload"><span>${icon('file')}My own files</span></label></div><label class="field">Evaluation name<input name="name" required maxlength="120" value="My evaluation" autocomplete="off"></label><div id="sample-fields"><label class="field">Sector<select name="sector">${Object.entries(sectors).map(([id,n])=>`<option value="${id}">${n}</option>`).join('')}</select></label><div class="sample-description">${icon('info')}<p><strong>8 cases · 2 systems · 2 trials per sector</strong>Synthetic observations demonstrate scoring, missing data, and policy violations. No model API calls are made.</p></div></div><div id="upload-fields" hidden><p class="field-hint"><a href="#data" class="text-link">Open the guided data requirements ${icon('arrow')}</a><br>Use the LTEF v1 schema. The profile file determines the sector. Only the resulting report is stored.</p>${[['cases','Case dataset','JSONL','.jsonl,.ndjson,.txt'],['observations','Observation bundle','JSON','.json'],['profile','Sector profile','JSON','.json']].map(([name,title,format,accept])=>`<label class="upload-field"><span><strong>${title}</strong><small>${format}</small></span><input type="file" name="${name}" accept="${accept}"></label>`).join('')}<div class="sample-downloads">Download examples: <a href="/samples/cases.jsonl" download>Cases</a><a href="/samples/observations.json" download>Observations</a><a href="/samples/profile/finance" download>Profile</a></div><p class="field-hint">Up to 2,000 cases and 10,000 case/system/trial combinations. Combined files must stay below 11 MB.</p></div><div id="run-error" class="form-error" role="alert" hidden></div><div class="dialog-actions"><button type="button" class="button secondary" data-close>Cancel</button><button type="submit" class="button primary" id="run-submit">Run evaluation ${icon('arrow')}</button></div></form>`,'run-dialog');
  $('#dialog').querySelectorAll('[name="mode"]').forEach(input=>input.onchange=()=>{const upload=input.value==='upload';$('#sample-fields').hidden=upload;$('#upload-fields').hidden=!upload;$('#dialog').querySelectorAll('input[type="file"]').forEach(f=>f.required=upload);});
  $('#run-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=$('#run-submit'),error=$('#run-error');button.disabled=true;button.textContent='Evaluating…';form.setAttribute('aria-busy','true');error.hidden=true;$('#dialog').querySelectorAll('[data-close]').forEach(b=>b.disabled=true);
    try{const data={mode:form.elements.mode.value,name:form.elements.name.value,sector:form.elements.sector.value};if(data.mode==='upload'){let bytes=0;for(const key of ['cases','observations','profile']){const file=form.elements[key].files[0];if(!file)throw Error('Choose all three input files.');bytes+=file.size;if(bytes>11*1024*1024)throw Error('Combined files must be below 11 MB.');data[key]=await file.text();}}const run=await api('/api/runs',{method:'POST',body:JSON.stringify(data)});await refreshSession();$('#dialog').close();state.resultsTab='summary';navigate('results/'+run.id);toast('Evaluation complete. Your report is saved.');}
    catch(err){error.textContent=err.message;error.hidden=false;error.focus();}
    finally{button.disabled=false;button.innerHTML='Run evaluation '+icon('arrow');form.removeAttribute('aria-busy');$('#dialog').querySelectorAll('[data-close]').forEach(b=>b.disabled=false);}
  };
}
function bindPublic(){
  document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{if(state.view==='welcome'){e.preventDefault();$('#'+a.dataset.scroll)?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}else{sessionStorage.setItem('ltef-scroll',a.dataset.scroll);}});
  document.querySelectorAll('[data-role-preview]').forEach(b=>b.onclick=()=>{state.landingRole=b.dataset.rolePreview;document.querySelectorAll('[data-role-preview]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#role-preview-body').innerHTML=rolePreview();});
  $('[data-action="password"]')?.addEventListener('click',event=>{const input=$('#auth-password');input.type=input.type==='password'?'text':'password';event.currentTarget.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');});
  if($('#auth-form'))$('#auth-form').onsubmit=async event=>{event.preventDefault();if(state.authBusy)return;const signup=state.view==='signup',form=event.target,button=$('button[type="submit"]',form),error=$('#auth-error');state.authBusy=true;button.disabled=true;button.textContent=signup?'Creating account…':'Signing in…';error.hidden=true;try{const data={email:form.elements.email.value,password:form.elements.password.value};if(signup)data.name=form.elements.name.value;applySession(await api('/api/auth/'+(signup?'register':'login'),{method:'POST',body:JSON.stringify(data)}));form.reset();state.run=null;state.search='';state.sector='all';state.group='quality';navigate('workspace');}catch(err){error.textContent=err.message;error.hidden=false;}finally{state.authBusy=false;button.disabled=false;button.innerHTML=(signup?'Create account':'Sign in')+' '+icon('arrow');}};
  const pending=sessionStorage.getItem('ltef-scroll');if(pending&&state.view==='welcome'){sessionStorage.removeItem('ltef-scroll');requestAnimationFrame(()=>$('#'+pending)?.scrollIntoView());}
}
function bindShared(){
  bindDetails();
  document.querySelectorAll('[data-resource]').forEach(b=>b.onclick=()=>{state.resource=b.dataset.resource;render();});
  document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{state.group=b.dataset.group;render();$('#tab-'+state.group)?.focus({preventScroll:true});});
  document.querySelectorAll('[data-result-tab]').forEach(b=>b.onclick=()=>{state.resultsTab=b.dataset.resultTab;render();$('#result-tab-'+state.resultsTab)?.focus({preventScroll:true});});
}
function bindDetails(){document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>showMetric(b.dataset.metric));document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>showCase(b.dataset.case,Number(b.dataset.trial)));}
function closeMenu(){const sidebar=$('#sidebar');if(sidebar)sidebar.classList.remove('open');const scrim=$('.nav-scrim');if(scrim)scrim.hidden=true;$('[data-action="menu"]')?.setAttribute('aria-expanded','false');}
function bindWorkspace(){
  bindData();
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.action;if(action==='new')openRun();if(action==='export')exportReport();if(action==='menu'){$('#sidebar').classList.toggle('open');const open=$('#sidebar').classList.contains('open');$('.nav-scrim').hidden=!open;b.setAttribute('aria-expanded',String(open));if(open)$('#sidebar .nav-item').focus();}if(action==='close-menu')closeMenu();if(action==='logout'){b.disabled=true;try{const data=await api('/api/auth/logout',{method:'POST',body:'{}'});clearAccount();applySession(data);navigate('signin');}catch(error){toast(error.message);b.disabled=false;}}});
  if($('#run-search'))$('#run-search').oninput=e=>{state.search=e.target.value;$('#evaluation-list').innerHTML=runList(state.runs.filter(r=>(state.sector==='all'||r.sector===state.sector)&&r.name.toLowerCase().includes(state.search.toLowerCase())));};
  if($('#sector-filter'))$('#sector-filter').onchange=e=>{state.sector=e.target.value;render();};
  if($('#system-select'))$('#system-select').onchange=e=>{state.system=e.target.value;render();};
  if($('#case-filter'))$('#case-filter').onchange=e=>{state.caseFilter=e.target.value;render();};
  for(const which of ['baseline','candidate'])if($('#'+which+'-select'))$('#'+which+'-select').onchange=e=>{state[which]=e.target.value;state.comparison=null;$('#comparison-results').innerHTML=busyPage();loadComparison();};
}
$('#dialog').addEventListener('close',()=>{if(dialogTrigger?.isConnected)dialogTrigger.focus({preventScroll:true});});
$('#dialog').addEventListener('cancel',e=>{if($('#run-form')?.getAttribute('aria-busy')==='true')e.preventDefault();});
$('#dialog').addEventListener('click',e=>{if(e.target!==$('#dialog')||$('#run-form')?.getAttribute('aria-busy')==='true')return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();});
window.addEventListener('hashchange',route);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar')?.classList.contains('open')){closeMenu();$('[data-action="menu"]')?.focus();}});
// Refresh account identity and access on return, including when a detail dialog is open.
async function recheckAccess(){
  if(!state.ready||state.authBusy)return;
  try{const changed=await refreshSession();if(changed)await route();}catch{/* Explicit actions surface connection failures. */}
}
window.addEventListener('focus',recheckAccess);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)recheckAccess();});
(async()=>{try{await refreshSession();state.ready=true;await route();}catch(error){$('#app').innerHTML=`<main id="main" class="boot-screen"><h1>Let’s reconnect.</h1><p>${esc(error.message)}</p><p>Check that your local LTEF server is running.</p><button id="retry" class="button primary">Try again ${icon('arrow')}</button></main>`;$('#retry').onclick=()=>location.reload();}})();
